// Upstream sanitizeStatusText replaces newlines, tabs and carriage returns
// with spaces, collapses space runs, and trims the ends.
func TestFooterSanitizesExtensionStatuses(t *testing.T) {
	if got := sanitizeStatusText("line1\n\tline2   x"); got != "line1 line2 x" {
		t.Fatalf("sanitize = %q; want %q", got, "line1 line2 x")
	}
	if got := sanitizeStatusText("\r\n  padded  \t"); got != "padded" {
		t.Fatalf("sanitize = %q; want %q", got, "padded")
	}
}

// Upstream sanitizeStatusText only rewrites \r, \n and \t and only collapses
// ASCII space runs, so other whitespace (NBSP, vertical tab, ideographic space)
// survives in the footer.
func TestFooterStatusSanitizerKeepsNonCollapsedWhitespace(t *testing.T) {
	for _, test := range []struct{ input, want string }{
		{"a\u00a0b", "a\u00a0b"},
		{"a\vb", "a\vb"},
		{"a\fb", "a\fb"},
		{"a\u3000b", "a\u3000b"},
		{"a \u00a0 b", "a \u00a0 b"},
		{"\u00a0 padded \u00a0", "padded"},
	} {
		if got := sanitizeStatusText(test.input); got != test.want {
			t.Fatalf("sanitize(%q) = %q; want %q", test.input, got, test.want)
		}
	}
}

// pi v1.4.0 packages/coding-agent/src/modes/interactive/components/footer.ts
// sorts extension status keys with JavaScript localeCompare before rendering.
func TestFooterStatusesUseUpstreamLocaleOrdering(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)

	path := filepath.Join(t.TempDir(), "session.jsonl")
	if err := os.WriteFile(path, []byte("{\"type\":\"session\",\"version\":3,\"id\":\"s\",\"timestamp\":\"t\",\"cwd\":\"/p\"}\n"), 0o644); err != nil {
		t.Fatalf("write session: %v", err)
	}
	manager, err := coding.OpenSession(path, "", "")
	if err != nil {
		t.Fatalf("open session: %v", err)
	}
	footer := NewFooterComponent(&fakeFooterSession{manager: manager}, &fakeFooterData{
		statuses: map[string]string{"A": "upper", "a": "lower"},
	})
	lines := footer.Render(200)
	if len(lines) != 1 {
		t.Fatalf("footer lines = %d, want 1", len(lines))
	}
	line := coding.StripAnsi(lines[0])
	if lower, upper := strings.Index(line, "lower"), strings.Index(line, "upper"); lower < 0 || upper < 0 || lower >= upper {
		t.Fatalf("status order = %q, want locale order lower before upper", line)
	}
}

// Upstream footer.ts uses path.resolve on both inputs, so a relative cwd under
// an absolute home still shortens; filepath.Clean left it relative.
func TestFormatCwdForFooterResolvesRelativeCwd(t *testing.T) {
	home, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	if got, want := FormatCwdForFooter("project", home), "~"+string(filepath.Separator)+"project"; got != want {
		t.Fatalf("FormatCwdForFooter = %q, want %q", got, want)
	}
}

// TestFooterLineSanitizesStoredCwd pins the footer against terminal control
// injection from a session file (D450). Reference: pi v1.5.0 f9a26365
// modes/interactive/components/footer.ts:165 builds its pwd from
// `formatCwdForFooter(sessionManager.getCwd())` without sanitizing it, while the
// port sanitizes untrusted terminal text (D342, D422). The footer is always
// visible, so a planted session shows the sequences as soon as it is opened,
// with no command required.
func TestFooterLineSanitizesStoredCwd(t *testing.T) {
	line := FooterLine(FooterInput{
		Cwd:         "/tmp/" + storedPayload,
		ModelID:     storedPayload,
		Statuses:    []string{storedPayload},
		ModelWindow: 1000,
	}, 200)
	assertOnlyThemeEscapes(t, []string{line})
}

// footer.ts calls truncateToWidth (pi v1.5.0 f9a26365 tui/src/utils.ts:1186),
// whose ellipsis branch returns a text that already fits instead of clipping
// the ellipsis: at width 2, "ab" stays "ab" while "日本語" becomes "..". The
// port short-circuited every width <= 3 to the ellipsis, so a fitting footer
// value was replaced by dots (D433).
func TestFooterTruncateKeepsFittingText(t *testing.T) {
	for _, tc := range []struct {
		text string
		w    int
		want string
	}{
		{"ab", 2, "ab"},
		{"a", 2, "a"},
		{"a", 1, "a"},
		{"", 2, ""},
		{"abc", 3, "abc"},
		{"abc", 4, "abc"},
		{"abcdef", 5, "ab..."},
		// Text wider than the budget still collapses to the ellipsis.
		{"abc", 2, ".."},
		{"日本語", 2, ".."},
		{"日本語", 3, "..."},
	} {
		if got := FooterTruncate(tc.text, tc.w); got != tc.want {
			t.Errorf("FooterTruncate(%q, %d) = %q, want %q", tc.text, tc.w, got, tc.want)
		}
	}
}

// elapsedTestComponent renders a line that changes with its value, mimicking the
// shell elapsed label.
type elapsedTestComponent struct{ value string }

func (c *elapsedTestComponent) Render(int) []string { return []string{"Elapsed " + c.value} }
func (c *elapsedTestComponent) Invalidate()         {}
func (c *elapsedTestComponent) AnimationFrame(time.Time) (bool, time.Duration) {
	return true, time.Second
}

// TestAltScreenWritesTheUpdatedElapsed pins that a repaint through the real
// fullscreen paint path (AltScreen.doRender -> RenderLayoutFrame -> scroll
// content) writes a changed elapsed line without any interaction. If this ever
// returns cached lines, the label freezes until the next click.
func TestAltScreenWritesTheUpdatedElapsed(t *testing.T) {
	terminal := &recordingTerminal{fakeRendererTerminal: &fakeRendererTerminal{width: 60, height: 10}}
	screen := tui.NewAltScreen(terminal, false, t.TempDir(), tui.AltScreenOptions{})
	t.Cleanup(func() { screen.Stop(tui.TuiStopOptions{}) })

	elapsed := &elapsedTestComponent{value: "1.0s"}
	chat := &tui.Container{}
	chat.AddChild(elapsed)
	document := &tui.Container{}
	document.AddChild(chat)
	transcript := tui.NewScrollView(document, tui.ScrollViewOptions{Follow: "end", Primary: true})
	root := tui.NewVStack(nil, tui.StackOptions{})
	root.AddChild(transcript)
	screen.SetLayoutRoot(root)

	screen.Start()
	screen.RenderNow(false)
	screen.RenderNow(false)
	if !terminal.hasWrite("1.0s") {
		t.Fatalf("initial elapsed not written; writes=%q", terminal.joinedWrites())
	}

	elapsed.value = "2.0s"
	screen.RenderNow(false)
	if !terminal.hasWrite("2.0s") {
		t.Fatalf("updated elapsed not written; writes=%q", terminal.joinedWrites())
	}
}

// TestMessageComponentsDoNotStackZoneMarkers pins that rendering a message
// twice does not stack OSC 133 markers. Both components used to write the
// markers into the lines their container returned; those lines are the
// container's render cache now shared with the parent, so writing into them
// grew the markers on every paint (and made every frame miss the caches).
func TestMessageComponentsDoNotStackZoneMarkers(t *testing.T) {
	newRendererTestTheme(t)

	user := NewUserMessageComponent("hello there", nil, 0, nil)
	first := strings.Join(user.Render(40), "\n")
	second := strings.Join(user.Render(40), "\n")
	if first != second {
		t.Fatalf("second render differs:\n%q\n%q", first, second)
	}
	if got := strings.Count(second, osc133ZoneStart); got != 1 {
		t.Fatalf("zone-start markers = %d, want 1:\n%q", got, second)
	}
	if got := strings.Count(second, osc133ZoneEnd); got != 1 {
		t.Fatalf("zone-end markers = %d, want 1:\n%q", got, second)
	}

	assistantMessage := &ai.AssistantMessage{
		API: ai.APIAnthropicMessages, Provider: "test", Model: "m",
		Content: ai.ContentList{ai.TextContent{Text: "hi"}},
	}
	assistant := NewAssistantMessageComponent(assistantMessage, false, nil, "Thinking...", 0, nil)
	firstA := strings.Join(assistant.Render(40), "\n")
	secondA := strings.Join(assistant.Render(40), "\n")
	if firstA != secondA {
		t.Fatalf("assistant second render differs:\n%q\n%q", firstA, secondA)
	}
	if got := strings.Count(secondA, osc133ZoneStart); got != 1 {
		t.Fatalf("assistant zone-start markers = %d, want 1:\n%q", got, secondA)
	}
}

// TestFormatTokensExtendsPastAMillion covers D513: upstream footer.ts
// formatTokens stops at M, so a session that has burned billions of tokens
// renders "4295M" or "1250000M" and the number grows without bound. The port
// continues the same band pattern with B and T.
func TestFormatTokensExtendsPastAMillion(t *testing.T) {
	for _, testCase := range []struct {
		count int64
		want  string
	}{
		// The upstream range is unchanged.
		{999, "999"},
		{1000, "1.0k"},
		{9999, "10.0k"},
		{10000, "10k"},
		{999999, "1000k"},
		{1000000, "1.0M"},
		{9999999, "10.0M"},
		{10000000, "10M"},
		// Past a million the units continue.
		{999999999, "1000M"},
		{1000000000, "1.0B"},
		{1234567890, "1.2B"},
		{4295000000, "4.3B"},
		{9999999999, "10.0B"},
		{10000000000, "10B"},
		{999999999999, "1000B"},
		{1000000000000, "1.0T"},
		{1234567890123, "1.2T"},
	} {
		if got := FormatTokens(testCase.count); got != testCase.want {
			t.Errorf("FormatTokens(%d) = %q, want %q", testCase.count, got, testCase.want)
		}
	}
	// The simple form keeps whole units, so it truncates the same bands.
	for _, testCase := range []struct {
		count int64
		want  string
	}{
		{999999999, "1000M"},
		{1000000000, "1B"},
		{1234567890, "1B"},
		{1000000000000, "1T"},
	} {
		if got := FormatTokensSimple(testCase.count); got != testCase.want {
			t.Errorf("FormatTokensSimple(%d) = %q, want %q", testCase.count, got, testCase.want)
		}
	}
}

// backgroundFooterSession is a footer session with calls running in the
// background.
type backgroundFooterSession struct {
	*fakeFooterSession
	running int
}

func (s *backgroundFooterSession) BackgroundCallCount() int { return s.running }

// D538: once a backgrounded call's handle line scrolls away, nothing said a
// command was still running. The footer shows how many are, among the statuses,
// and nothing when none are.
func TestFooterShowsRunningBackgroundCalls(t *testing.T) {
	newRendererTestTheme(t)
	session := &backgroundFooterSession{fakeFooterSession: &fakeFooterSession{
		manager: coding.InMemorySession("/p", nil, nil), model: &ai.Model{ID: "m", ContextWindow: 1000},
	}}
	footer := NewFooterComponent(session, &fakeFooterData{statuses: map[string]string{}})
	for running, want := range map[int]string{0: "", 1: "1 call in background", 2: "2 calls in background"} {
		session.running = running
		footer.Invalidate()
		line := coding.StripAnsi(strings.Join(footer.Render(200), "\n"))
		if want == "" {
			if strings.Contains(line, "background") {
				t.Fatalf("no running call, footer = %q", line)
			}
			continue
		}
		if !strings.Contains(line, want) {
			t.Fatalf("%d running, footer = %q, want %q", running, line, want)
		}
	}
}

// D537: a scheduled loop is invisible between its runs. The footer shows how many
// jobs are scheduled, among the statuses, and nothing when none are.
func TestFooterShowsScheduledLoops(t *testing.T) {
	newRendererTestTheme(t)
	footer := NewFooterComponent(&fakeFooterSession{
		manager: coding.InMemorySession("/p", nil, nil), model: &ai.Model{ID: "m", ContextWindow: 1000},
	}, &fakeFooterData{statuses: map[string]string{}})
	scheduled := 0
	footer.SetLoopCount(func() int { return scheduled })
	for count, want := range map[int]string{0: "", 1: "1 loop scheduled", 3: "3 loops scheduled"} {
		scheduled = count
		footer.Invalidate()
		line := coding.StripAnsi(strings.Join(footer.Render(200), "\n"))
		if want == "" {
			if strings.Contains(line, "loop") {
				t.Fatalf("no loop, footer = %q", line)
			}
			continue
		}
		if !strings.Contains(line, want) {
			t.Fatalf("%d loops, footer = %q, want %q", count, line, want)
		}
	}
}
